using System.Net;using System.Text.Json;using Microsoft.AspNetCore.Mvc.Testing;using Xunit;
namespace CRM.UnitTests;public sealed class LeadsFunnelInsightHardeningTests{[Fact]public async Task ExpectedKpisAndFlags_AreStable(){using var f=new WebApplicationFactory<Program>();using var c=f.CreateClient();var r=await c.GetAsync("/api/crm/foundation/insights/leads-funnel");Assert.Equal(HttpStatusCode.OK,r.StatusCode);using var d=JsonDocument.Parse(await r.Content.ReadAsStringAsync());var x=d.RootElement;Assert.Equal("FoundationMock",x.GetProperty("sourceMode").GetString());var names=x.GetProperty("metrics").EnumerateArray().Select(m=>m.GetProperty("name").GetString()).ToArray();Assert.Contains("LeadConversionRate",names);Assert.Contains("QualifiedLeads",names);Assert.False(x.GetProperty("productiveRuntimeEnabled").GetBoolean());Assert.False(x.GetProperty("portalRuntimeEnabled").GetBoolean());Assert.False(x.GetProperty("commonDbRuntimeEnabled").GetBoolean());}}